// ═══════════════════════════════════════════════════════
// VALIDAR + MAPEAR COLUMNAS
// Detecta automáticamente los nombres de columnas del Excel
// y los mapea a los campos de ospos_people
// ═══════════════════════════════════════════════════════

const items     = $input.all();
const cfg       = $('⚙️ Configuración').first().json;
const resultado = { validos: [], rechazados: [], total_filas: items.length };

// ── Mapa de alias bilingue ES+EN (detecta variaciones de nombres de columna) ──────────────
const ALIAS = {
  first_name:   ['nombre','primer_nombre','nombres','paciente','nombre_paciente','nombre_del_paciente',
                 'first_name','firstname','first','name','given_name','forename','patient_name','patient'],
  last_name:    ['apellido','apellido_paterno','apellidop','primer_apellido','ap_paterno','paterno',
                 'last_name','lastname','last','surname','family_name','second_name'],
  last_name2:   ['apellido_materno','apellidom','segundo_apellido','ap_materno','materno',
                 'last_name2','last_name_2','middle_name','second_last_name','mothers_last_name','maternal_surname'],
  email:        ['email','correo','correo_electronico','e-mail','mail','correo_del_paciente',
                 'email_address','electronic_mail'],
  phone_number: ['telefono','telefono_fijo','fijo','tel','tel_casa','num_telefono','numero_telefono','telefono1',
                 'phone','phone_number','telephone','landline','home_phone','work_phone','phone_1','tel_number'],
  celular:      ['celular','cel','movil','telefono_movil','tel_celular','celularwhatsapp','whatsapp','num_celular','telefono2',
                 'mobile','cell','cell_phone','cellphone','mobile_phone','mobile_number','cell_number','phone_2','whatsapp_number'],
  nacimiento:   ['nacimiento','fecha_nacimiento','fecha_nac','f_nacimiento','cumpleanos','fecnac','fecha_de_nacimiento',
                 'birthdate','birth_date','date_of_birth','dob','birthday','born','fecha_nac_'],
  genero:       ['genero','sexo','sexo_biologico','genero_biologico',
                 'gender','sex','biological_sex'],
  address_1:    ['direccion','calle','domicilio','calle_numero','calle_y_numero','domicilio_calle',
                 'address','address_1','street','street_address','address_line_1','address1','street_name'],
  address_2:    ['colonia','colonia_fracc','fraccionamiento','barrio','colonia_barrio',
                 'address_2','neighborhood','suburb','district','address_line_2','address2','locality'],
  city:         ['ciudad','municipio','delegacion','alcaldia','ciudad_municipio',
                 'city','town','municipality','borough'],
  state:        ['estado','entidad','entidad_federativa',
                 'state','province','region','state_province'],
  zip:          ['cp','codigo_postal','c_p','cod_postal','num_cp',
                 'zip','zip_code','postal_code','postcode','zip_postal'],
  comments:     ['comentarios','notas','observaciones','nota','comentario',
                 'comments','notes','remarks','observations','note','description']
};

// ── Helper: encontrar valor por alias ─────────────────────────────────────────
function findVal(row, campo) {
  const aliases = ALIAS[campo] || [];
  for (const key of Object.keys(row)) {
    const keyNorm = key.toLowerCase().trim()
      .replace(/\s+/g,'_')
      .normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    if (aliases.includes(keyNorm)) {
      return String(row[key] || '').trim();
    }
  }
  return '';
}

// ── Helper: limpiar teléfono → solo dígitos ──────────────────────────────────
function cleanPhone(raw) {
  if (!raw) return '';
  const digits = String(raw).replace(/\D/g,'');
  if (digits.length === 10) return digits;
  if (digits.length >= 12 && digits.startsWith('52')) return digits.slice(2, 12);
  return digits.slice(0, 15); // max 15 dígitos
}

// ── Helper: escapar SQL (previene inyección básica) ──────────────────────────
function esc(str) {
  return String(str || '').replace(/'/g,"''").replace(/\\/g,'\\\\').trim();
}

// ── Helper: normalizar fecha YYYY-MM-DD ──────────────────────────────────────
function cleanDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  // Formatos: DD/MM/YYYY, DD-MM-YYYY, MM/DD/YYYY, YYYY-MM-DD
  const patterns = [
    { re: /^(\d{4})-(\d{2})-(\d{2})$/,       fmt: (m) => `${m[1]}-${m[2]}-${m[3]}` },
    { re: /^(\d{2})\/(\d{2})\/(\d{4})$/,       fmt: (m) => `${m[3]}-${m[2]}-${m[1]}` },
    { re: /^(\d{2})-(\d{2})-(\d{4})$/,         fmt: (m) => `${m[3]}-${m[2]}-${m[1]}` },
    { re: /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/,   fmt: (m) => `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}` },
  ];
  for (const p of patterns) {
    const m = s.match(p.re);
    if (m) return p.fmt(m);
  }
  return null;
}

// ── Helper: normalizar género ─────────────────────────────────────────────────
function cleanGenero(raw) {
  if (!raw) return 'masculino';
  const s = raw.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if (['f','femenino','mujer','female','fem','w','woman','girl','she','women','feminin'].includes(s)) return 'femenino';
  if (['m','masculino','hombre','male','man','boy','he','h','masc','masculine'].includes(s)) return 'masculino';
  return 'masculino';
}

// ── Procesar cada fila ────────────────────────────────────────────────────────
for (const item of items) {
  const row = item.json;

  // Skip filas vacías
  const firstVal = Object.values(row)[0];
  if (!firstVal || String(firstVal).trim() === '') continue;

  const first_name = esc(findVal(row, 'first_name').toUpperCase());
  const last_name  = esc(findVal(row, 'last_name').toUpperCase());
  const last_name2 = esc(findVal(row, 'last_name2').toUpperCase());
  const email      = esc(findVal(row, 'email').toLowerCase());
  const phone_raw  = findVal(row, 'phone_number');
  const celular_raw= findVal(row, 'celular');
  const phone_number = cleanPhone(phone_raw);
  const celular      = cleanPhone(celular_raw);
  const nacimiento   = cleanDate(findVal(row, 'nacimiento'));
  const genero       = cleanGenero(findVal(row, 'genero'));
  const address_1    = esc(findVal(row, 'address_1'));
  const address_2    = esc(findVal(row, 'address_2'));
  const city         = esc(findVal(row, 'city'));
  const state        = esc(findVal(row, 'state'));
  const zip          = cleanPhone(findVal(row, 'zip')); // solo dígitos
  const comments     = esc(findVal(row, 'comments'));

  // ── Validaciones requeridas ──────────────────────────────────────────────
  const errores = [];
  if (!first_name) errores.push('Nombre vacío');
  if (!last_name)  errores.push('Apellido paterno vacío');
  if (!phone_number && !celular) errores.push('Sin teléfono ni celular');
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errores.push(`Email inválido: ${email}`);

  const paciente = {
    practica_id:  cfg.practica_id,
    first_name,
    last_name,
    last_name2,
    email,
    phone_number,
    celular,
    nacimiento,
    genero,
    address_1,
    address_2,
    city,
    state,
    zip,
    country:   'México',
    comments
  };

  if (errores.length > 0) {
    resultado.rechazados.push({ ...paciente, errores: errores.join(' | '), _raw: JSON.stringify(row) });
    console.warn('[IMPORT RECHAZADO]', first_name, last_name, '→', errores.join(', '));
  } else {
    resultado.validos.push({ json: paciente });
  }
}

console.log(`[IMPORT] Total filas: ${resultado.total_filas} | Válidos: ${resultado.validos.length} | Rechazados: ${resultado.rechazados.length}`);

if (resultado.rechazados.length > 0) {
  console.warn('[IMPORT RECHAZADOS]', JSON.stringify(resultado.rechazados.map(r => ({ nombre: `${r.first_name} ${r.last_name}`, errores: r.errores }))));
}

// Si no hay válidos, retornar señal de vacío
if (resultado.validos.length === 0) {
  return [{ json: { _import_vacio: true, total_rechazados: resultado.rechazados.length, mensaje: 'No hay registros válidos para importar' } }];
}

return resultado.validos;

