// Referenciamos el nodo de búsqueda porque el UPDATE de MySQL solo devuelve {affectedRows}
const d = $('🔍 Buscar Paciente en BD').item.json;
return [{ json: {
  person_id:    d.person_id_encontrado,
  accion:       'UPDATE',
  paciente:     `${d._fn} ${d._ln} ${d._ln2}`.trim(),
  email:        d._email,
  celular:      d._celular,
  phone:        d._phone
}}];

// Combina el nuevo person_id con los datos del paciente del nodo de búsqueda
const idRow   = $input.first().json;
const origen  = $('🔍 Buscar Paciente en BD').item.json;

const nuevoId = idRow.nuevo_id;
if (!nuevoId) return [{ json: { _error: 'No se obtuvo person_id', origen } }];

return [{ json: {
  nuevo_id:   nuevoId,
  practica_id: origen._practica_id,
  nombre:      origen._fn,
  apellidop:   origen._ln,
  apellidom:   origen._ln2,
  email:       origen._email,
  telefono:    origen._phone,
  celular:     origen._celular,
  nacimiento:  origen._nacimiento,
  genero:      origen._genero,
  direccion:   origen._address1,
  colonia:     origen._address2,
  municipio:   origen._city,
  estado:      origen._state,
  cp:          origen._zip || 0
}}];

const d    = $('🔍 Buscar Paciente en BD').item.json;
const newId = $('🆔 Obtener Nuevo person_id').item?.json?.nuevo_id;
return [{ json: {
  person_id: newId,
  accion:    'INSERT',
  paciente:  `${d._fn} ${d._ln} ${d._ln2}`.trim(),
  email:     d._email,
  celular:   d._celular,
  phone:     d._phone
}}];

// ── Reporte Final de Importación ────────────────────────────────────
const todosLosItems = $input.first().json.data || [];

const actualizados = todosLosItems.filter(i => i.accion === 'UPDATE');
const insertados   = todosLosItems.filter(i => i.accion === 'INSERT');
const errores      = todosLosItems.filter(i => i._error);

const resumen = {
  status:          '✅ Importación completada',
  timestamp:       new Date().toLocaleString('es-MX', { timeZone: 'America/Monterrey' }),
  total_procesados: todosLosItems.length,
  insertados_nuevos: insertados.length,
  actualizados:    actualizados.length,
  errores:         errores.length,
  detalle_insertados: insertados.map(i => ({ id: i.person_id, nombre: i.paciente, email: i.email, celular: i.celular })),
  detalle_actualizados: actualizados.map(i => ({ id: i.person_id, nombre: i.paciente, email: i.email, celular: i.celular })),
  detalle_errores: errores.map(i => ({ paciente: i.paciente, error: i._error }))
};

console.log('[IMPORT FINALIZADO]', JSON.stringify({
  insertados: resumen.insertados_nuevos,
  actualizados: resumen.actualizados,
  errores: resumen.errores
}));

return [{ json: resumen }];
